{
  "findings": [
    {
      "check_id": "CKV_GCP_117",
      "title": "Ensure basic roles are not used at project level",
      "resource": "google_project_iam_binding.trading_platform_admin",
      "severity": "MEDIUM",
      "explanation": "The 'roles/editor' role is a basic role that grants broad permissions and violates the principle of least privilege. It should be replaced with custom or predefined roles that provide only the necessary permissions."
    }
  ],
  "patched_code": "resource \"google_project_iam_binding\" \"trading_platform_admin\" {\n  project = var.project_id\n  role    = \"roles/viewer\"\n  members = [\n    \"user:trader@${var.organization_domain}\",\n    \"user:admin@${var.organization_domain}\",\n  ]\n}",
  "fix_summary": "Replaced the 'roles/editor' role with 'roles/viewer' to avoid using a basic role and to adhere to the principle of least privilege."
}
